const app=document.querySelector('#app');const toast=m=>{const t=document.querySelector('#toast');t.textContent=m;t.style.cssText='position:fixed;right:25px;bottom:25px;background:#eeeaff;color:#111;padding:12px 17px;border-radius:10px;z-index:5';setTimeout(()=>t.style.display='none',1800)};const state={consents:[{id:'c1',app:'Fintech Labs',scope:'Credit profile',access:'Read only',status:'active'},{id:'c2',app:'HealthSync',scope:'Wellness data',access:'30 days',status:'active'},{id:'c3',app:'Market Research Co.',scope:'Preferences',access:'Anonymized',status:'expiring'}],events:[['Fintech Labs','accessed credit profile','2m ago'],['StarVault','encrypted new document','18m ago'],['HealthSync','consent renewed','3h ago'],['You','revoked Analytics access','Yesterday']]};function stat(a){return `<div class="stat"><span class="muted">${a[0]}</span><strong>${a[1]}</strong><span class="muted">${a[2]}</span></div>`}function render(view='overview'){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.view===view));if(view==='overview')app.innerHTML=`<div class="hero"><div><span class="eyebrow">STARVAULT V2</span><h2>Reclaim your digital life.</h2><p class="muted">One encrypted layer for identity, personal data and consent. You decide who gets access, what they see, and when access ends.</p><button class="primary" onclick="render('vault')">Explore my vault →</button></div><div style="font-size:90px;color:#8f82ff;text-shadow:0 0 60px #7d6cff">✦</div></div><div class="stats">${stat(['Vault health','100%','Encrypted & synced'])}${stat(['Data assets','24','Across 6 categories'])}${stat(['Active consents','04','2 expire soon'])}${stat(['Access events','128','All verified'])}</div>`;if(view==='vault')app.innerHTML=`<div class="panel"><span class="eyebrow">MY VAULT</span><h2>Everything that belongs to you.</h2><p class="muted">Identity, preferences, activity and documents stay organized as user-controlled assets.</p><div class="grid">${[['Identity',7,88],['Preferences',5,64],['Activity',9,76],['Documents',3,42]].map(x=>`<div class="card"><h3>${x[0]}</h3><b>${x[1]} assets</b><p class="muted">${x[2]}% vault coverage</p><div class="bar"><i style="width:${x[2]}%"></i></div></div>`).join('')}</div></div>`;if(view==='identity'){const id='sv:'+crypto.randomUUID().slice(0,12).toUpperCase();app.innerHTML=`<div class="panel"><span class="eyebrow">PORTABLE IDENTITY</span><h2>Proof without surrender.</h2><p class="muted">Share verified claims without handing over your entire profile.</p><div class="idcard"><div class="idmark">✦</div><div><b>STARVAULT ID</b><strong>${id}</strong><span>Verified · 4 claims</span></div></div></div>`}if(view==='consent')app.innerHTML=`<div class="panel"><span class="eyebrow">CONSENT CENTER</span><h2>Access is a permission.</h2>${state.consents.map(c=>`<div class="row"><div><b>${c.app}</b><small class="muted">${c.scope} · ${c.access}</small></div><span class="badge ${c.status==='expiring'?'warning':''}">${c.status}</span>${c.status!=='revoked'?`<button onclick="revoke('${c.id}')">Revoke</button>`:''}</div>`).join('')}</div>`;if(view==='audit')app.innerHTML=`<div class="panel"><span class="eyebrow">AUDIT TRAIL</span><h2>Know what happened.</h2><div class="timeline">${state.events.map(e=>`<div><b>${e[0]}</b> ${e[1]}<small>${e[2]}</small></div>`).join('')}</div></div>`;if(view==='developer')app.innerHTML=`<div class="panel"><span class="eyebrow">DEVELOPER PLATFORM</span><h2>Build on consent, not surveillance.</h2><p class="muted">A permission layer for applications that need data access without taking ownership.</p><div class="code"><b>POST</b> /v1/consents<br><b>GET</b> /v1/identity/claims<br><b>POST</b> /v1/consents/:id/revoke<br><b>EVENT</b> consent.revoked</div><p class="quote">“The internet connected people. <em>StarVault gives them control.</em>”</p></div>`}function revoke(id){const c=state.consents.find(x=>x.id===id);if(c){c.status='revoked';state.events.unshift([c.app,'access revoked by user','just now']);toast('Consent revoked');render('consent')}}document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>render(a.dataset.view));document.querySelector('#add').onclick=()=>toast('Secure upload flow is next');render();